// Contract test for fixtures/places-response.json (Y-159).
//
// The fixture is a GET /api/places response body as yomp-api's own route handler emits it
// (generated by yomp-api's tests/unit/places.contract-fixture.test.ts, upstreams mocked).
// It is validated here against place.schema.json, so a schema change that would reject a
// real response fails in this repo's CI before any consumer pins the change. yomp-api
// re-validates it on every `npm test`, and yomp-android reads it in a unit test.
//
// Runs under Node's native test runner + type-stripping: `npm test` -> `node --test`.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import Ajv from "ajv";

const read = (rel: string) =>
  JSON.parse(readFileSync(fileURLToPath(new URL(`../${rel}`, import.meta.url)), "utf8"));

const schema = read("src/schemas/place.schema.json");
const fixture = read("fixtures/places-response.json");
const validate = new Ajv({ strict: false, allErrors: true }).compile(schema);

test("the fixture is a non-empty array of places", () => {
  assert.ok(Array.isArray(fixture));
  assert.ok(fixture.length > 0);
});

test("every place in the fixture validates against place.schema.json", () => {
  fixture.forEach((place: unknown, i: number) => {
    assert.equal(validate(place), true, `item ${i}: ${JSON.stringify(validate.errors)}`);
  });
});

test("the fixture exercises every schema property, so a removed field is noticed", () => {
  const seen = new Set<string>(fixture.flatMap((p: object) => Object.keys(p)));
  const missing = Object.keys(schema.properties).filter((k) => !seen.has(k));
  assert.deepEqual(missing, []);
});

test("the fixture carries a minimal place with only the required fields", () => {
  const required: string[] = schema.required;
  const minimal = fixture.find(
    (p: object) => Object.keys(p).length === required.length && required.every((k) => k in p),
  );
  assert.ok(minimal, "expected one place carrying exactly the required fields");
});

test("the validator is live: an unknown extra property is rejected", () => {
  assert.equal(validate({ ...fixture[0], unexpectedExtraField: "x" }), false);
});

test("the fixture holds no credentials, emails or user identifiers", () => {
  const text = JSON.stringify(fixture);
  assert.doesNotMatch(text, /Bearer\s|eyJ[A-Za-z0-9_-]{10,}|AIza[0-9A-Za-z_-]{20,}|@[a-z0-9-]+\.[a-z]{2,}/i);
  assert.doesNotMatch(text, /"(uid|userId|token|email)"/);
});
